{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ bs, be: i, ss, se: j, who })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush(); i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(args[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) l === '%%%' ? docs.push([]) : docs[docs.length - 1].push(l)
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)

  const out = []
  let conflict = false
  const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])
  let pos = 0, k = 0
  const stable = to => {
    if (to > pos) {
      if (mode === 'regions') out.push(`stable ${to - pos}`)
      else out.push(...base.slice(pos, to))
    }
  }
  while (k < all.length) {
    const first = all[k++]
    const group = [first]
    let end = first.be
    while (k < all.length && all[k].bs <= end) {
      end = Math.max(end, all[k].be)
      group.push(all[k++])
    }
    const start = first.bs
    stable(start)
    const baseL = base.slice(start, end)
    const sideLines = (side, doc) => {
      const cs = group.filter(c => c.who === side)
      if (!cs.length) return baseL
      const f = cs[0], l = cs[cs.length - 1]
      let mn = f, mx = l
      for (const c of cs) { if (c.bs < mn.bs) mn = c; if (c.be > mx.be) mx = c }
      return doc.slice(f.ss - (f.bs - start), l.se + (end - l.be))
    }
    const mi = sideLines(0, mine), th = sideLines(1, theirs)
    let res, label
    if (eq(mi, th)) { res = mi; label = group.length === 1 ? (first.who ? 'theirs' : 'mine') : 'both' }
    else if (eq(mi, baseL)) { res = th; label = 'theirs' }
    else if (eq(th, baseL)) { res = mi; label = 'mine' }
    else {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${mi.length} base=${baseL.length} theirs=${th.length}`)
      else {
        out.push('<<<<<<< mine', ...mi)
        if (mode === 'merge') out.push('||||||| base', ...baseL)
        out.push('=======', ...th, '>>>>>>> theirs')
      }
      pos = end
      continue
    }
    if (mode === 'regions') out.push(`${label} ${res.length}`)
    else out.push(...res)
    pos = end
  }
  stable(base.length)
  if (out.length) process.stdout.write(out.join('\n') + '\n')
  process.exitCode = conflict ? 1 : 0
}

main()
