const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export class UriError extends Error {}

export function parse(s) {
  let scheme, authority, query, fragment
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { scheme = m[1]; s = s.slice(m[0].length) }
  let i = s.indexOf('#')
  if (i >= 0) { fragment = s.slice(i + 1); s = s.slice(0, i) }
  i = s.indexOf('?')
  if (i >= 0) { query = s.slice(i + 1); s = s.slice(0, i) }
  if (s.startsWith('//')) {
    const rest = s.slice(2)
    const j = rest.search(/\//)
    authority = j >= 0 ? rest.slice(0, j) : rest
    s = j >= 0 ? rest.slice(j) : ''
  }
  return { scheme, authority, path: s, query, fragment }
}

function splitAuthority(a) {
  let userinfo, hostport = a
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); hostport = a.slice(at + 1) }
  const rb = hostport.lastIndexOf(']')
  const c = hostport.indexOf(':', rb + 1)
  let host = hostport, port
  if (c >= 0) { host = hostport.slice(0, c); port = hostport.slice(c + 1) }
  return { userinfo, host, port }
}

const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const ch = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(ch) ? ch : '%' + h.toUpperCase()
  })
}

function checkPct(s, name, line) {
  if (s !== undefined && /%(?![0-9A-Fa-f]{2})/.test(s)) {
    throw new UriError(`line ${line}: the ${name} has a truncated percent-encoding`)
  }
}

export function removeDots(path) {
  let inp = path, out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const j = inp.indexOf('/', 1)
      const seg = j >= 0 ? inp.slice(0, j) : inp
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

export function normalize(u, line) {
  let { scheme, authority, path, query, fragment } = u
  let ui, host, port
  if (authority !== undefined) ({ userinfo: ui, host, port } = splitAuthority(authority))
  checkPct(path, 'path', line)
  checkPct(ui, 'userinfo', line)
  checkPct(host, 'host', line)
  checkPct(query, 'query', line)
  checkPct(fragment, 'fragment', line)
  if (scheme !== undefined) scheme = lowerAscii(scheme)
  path = pct(path)
  if (query !== undefined) query = pct(query)
  if (fragment !== undefined) fragment = pct(fragment)
  let auth
  if (authority !== undefined) {
    if (ui !== undefined) ui = pct(ui)
    host = lowerAscii(pct(host))
    if (port !== undefined) {
      port = pct(port)
      if (port === '' || (scheme !== undefined && DEFAULT_PORTS[scheme] === port)) port = undefined
    }
    auth = (ui !== undefined ? ui + '@' : '') + host + (port !== undefined ? ':' + port : '')
  }
  path = removeDots(path)
  if (auth !== undefined && path === '') path = '/'
  return (scheme !== undefined ? scheme + ':' : '') + (auth !== undefined ? '//' + auth : '') +
    path + (query !== undefined ? '?' + query : '') + (fragment !== undefined ? '#' + fragment : '')
}

export function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) {
    return { ...ref, path: removeDots(ref.path) }
  }
  t.scheme = base.scheme
  if (ref.authority !== undefined) {
    return { ...ref, scheme: base.scheme, path: removeDots(ref.path) }
  }
  t.authority = base.authority
  t.fragment = ref.fragment
  if (ref.path === '') {
    t.path = base.path
    t.query = ref.query !== undefined ? ref.query : base.query
  } else {
    t.query = ref.query
    if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
    else {
      let merged
      if (base.authority !== undefined && base.path === '') merged = '/' + ref.path
      else merged = base.path.slice(0, base.path.lastIndexOf('/') + 1) + ref.path
      t.path = removeDots(merged)
    }
  }
  return t
}
