{"file_path":"src/merge.js","content":"const same = (a, b) => a.length === b.length && a.every((x, i) => x === b[i])

function changes(base, side, who) {
  const n = base.length
  const m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) { matches.push([i, j]); i++; j++ }
    else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  matches.push([n, m])
  const out = []
  let pi = 0
  let pj = 0
  for (const [mi, mj] of matches) {
    if (mi > pi || mj > pj) out.push({ who, bs: pi, be: mi, ss: pj, se: mj })
    pi = mi + 1
    pj = mj + 1
  }
  return out
}

export function merge(mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs)
  const sides = [mine, theirs]
  const result = []
  let pos = 0
  let k = 0
  while (k < all.length) {
    const group = [all[k++]]
    const start = group[0].bs
    let end = group[0].be
    while (k < all.length && all[k].bs <= end) {
      end = Math.max(end, all[k].be)
      group.push(all[k++])
    }
    if (start > pos) result.push({ kind: 'stable', lines: base.slice(pos, start) })
    pos = end
    if (group.length === 1) {
      const c = group[0]
      result.push({ kind: c.who ? 'theirs' : 'mine', lines: sides[c.who].slice(c.ss, c.se) })
      continue
    }
    const rep = sides.map((s, w) => {
      const cs = group.filter(c => c.who === w)
      if (!cs.length) return base.slice(start, end)
      const first = cs[0]
      const last = cs[cs.length - 1]
      const lo = Math.min(...cs.map(c => c.bs))
      const hi = Math.max(...cs.map(c => c.be))
      return s.slice(first.ss - (lo - start), last.se + (end - hi))
    })
    const b = base.slice(start, end)
    const [m, t] = rep
    if (same(m, t)) result.push({ kind: 'both', lines: m })
    else if (same(m, b)) result.push({ kind: 'theirs', lines: t })
    else if (same(t, b)) result.push({ kind: 'mine', lines: m })
    else result.push({ kind: 'conflict', mine: m, base: b, theirs: t })
  }
  if (pos < base.length) result.push({ kind: 'stable', lines: base.slice(pos) })
  return result
}
"}

