const fail = (m) => { throw new Fail(m) }

const newTable = () => ({ t: 'table', map: new Map(), header: false })

function walkTo(table, names, base) {
  let cur = table
  const path = [...base]
  for (const n of names) {
    path.push(n)
    let child = cur.map.get(n)
    if (!child) {
      child = newTable()
      cur.map.set(n, child)
    }
    if (child.t === 'table') cur = child
    else if (child.t === 'array' && child.aot) cur = child.items[child.items.length - 1]
    else fail(`${path.join('.')} is not a table`)
  }
  return cur
