import { readFileSync } from 'node:fs'

function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

const args = process.argv.slice(2)
let workers = 0
if (args.length === 1 && (args[0] === 'waves' || args[0] === 'explain')) {
  // ok
} else if (args.length === 2 && args[0] === 'pack') {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail('error: usage: cli.js waves|explain|pack <workers>')
const mode = args[0]

let input = ''
try { input = readFileSync(0, 'utf8') } catch { input = '' }
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const depLines = []
lines.forEach((raw, i) => {
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  const n = i + 1
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depLines.push(w.slice(1))
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})
for (const d of depLines) for (const x of d) if (!cost.has(x)) fail(`error: unknown task ${x}`)
for (const name of cost.keys()) deps.set(name, new Set())
for (const [a, ...rest] of depLines) for (const b of rest) deps.get(a).add(b)

const names = [...cost.keys()].sort(cmp)
const sdeps = new Map(names.map((n) => [n, [...deps.get(n)].sort(cmp)]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const dfs = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of sdeps.get(u)) {
      const s = state.get(v)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(v)).concat(v)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!s) dfs(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const n of names) if (!state.get(n)) dfs(n)
}

const start = new Map(), finish = new Map(), depth = new Map()
const visit = (u) => {
  if (finish.has(u)) return
  let s = 0n, d = 0
  for (const v of sdeps.get(u)) {
    visit(v)
    if (finish.get(v) > s) s = finish.get(v)
    if (depth.get(v) + 1 > d) d = depth.get(v) + 1
  }
  start.set(u, s); finish.set(u, s + cost.get(u)); depth.set(u, d)
}
names.forEach(visit)
let total = 0n
for (const f of finish.values()) if (f > total) total = f

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const n of names) (ws[depth.get(n)] ||= []).push(n)
  ws.forEach((w, k) => { out += `wave ${k}: ${w.join(' ')}\n` })
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const n of names) out += `${n} start=${start.get(n)} finish=${finish.get(n)} depth=${depth.get(n)}\n`
  out += `total ${total}\n`
} else {
  const prio = new Map()
