  const k = history.length
  out.push(`round ${k}: ${listed.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${total - active}`)
  if (active === 0n) break
  const w = listed.find((c) => counts.get(c) * 2n > active)
  if (w !== undefined) {
    result = `winner ${w}`
    break
  }
  let min = null
  for (const c of cont) if (min === null || counts.get(c) < min) min = counts.get(c)
  let tied = [...cont].filter((c) => counts.get(c) === min)
  for (let again = tied.length > 1; again; ) {
    again = false
    for (const h of history) {
      const vs = tied.map((c) => h.get(c))
      const m = vs.reduce((a, b) => (a < b ? a : b))
      if (vs.some((v) => v !== m)) {
        tied = tied.filter((c) => h.get(c) === m)
        again = tied.length > 1
        break
      }
    }
  }
  const el = tied.sort().pop()
  cont.delete(el)
  out.push(`eliminated ${el}`)
}
out.push(result)
if (mode === 'tally') process.stdout.write(`rounds ${history.length}\n${result}\n`)
else process.stdout.write(out.join('\n') + '\n')
