const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function int(field, s, least) {
  if (!INT.test(s) || BigInt(s) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    try {
      const d = f[0]
      const decl = d === 'bucket' || d === 'window' || d === 'route'
      if (!decl && d !== 'event') throw new Fail(`unknown directive ${d}`)
      if (d === 'bucket' && f.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
      if (d === 'window' && f.length !== 4) throw new Fail('expected window <name> <limit> <span>')
      if (d === 'route' && f.length < 3) throw new Fail('expected route <prefix> <policy>...')
      if (d === 'event' && f.length !== 3) throw new Fail('expected event <tick> <key>')
      if (decl && events.length) throw new Fail('declarations must come before the first event')
      if (d === 'bucket' || d === 'window') {
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        let p
        if (d === 'bucket') {
          const capacity = int('capacity', f[2], 1)
          const refill = int('refill', f[3], 0)
          const per = int('per', f[4], 1)
          p = { type: 'bucket', name: f[1], capacity, refill, per }
        } else {
          p = { type: 'window', name: f[1], limit: int('limit', f[2], 0), span: int('span', f[3], 1) }
        }
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], p)
      } else if (d === 'route') {
        if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        for (const n of f.slice(2)) if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
        routes.set(f[1], f.slice(2))
      } else {
        const tick = int('tick', f[1], 0)
        if (!NAME.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${f[1]} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, tickText: f[1], key: f[2] })
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  return { policies, routes, events }
}

function run({ policies, routes, events }) {
  const states = new Map() // policyName\0key -> state
  const stateFor = (p, key) => {
    const id = p.name + '\0' + key
    return states.get(id) ?? (states.set(id, null), id)
  }
  const get = (p, key, tick) => {
    const id = p.name + '\0' + key
    let s = states.get(id)
    if (!s) {
      s = p.type === 'bucket' ? { num: p.capacity * p.per, last: tick } : { ticks: [] }
      states.set(id, s)
    }
    if (p.type === 'bucket') {
      const cap = p.capacity * p.per
      s.num += p.refill * (tick - s.last)
      if (s.num > cap) s.num = cap
      s.last = tick
    } else {
      const cut = tick - p.span
      while (s.ticks.length && s.ticks[0] <= cut) s.ticks.shift()
    }
    return s
  }
  const prefixes = [...routes.keys()]
  const out = []
  const per = new Map()
  let ta = 0, td = 0
  for (const ev of events) {
    let best = null
    for (const pr of prefixes) if (ev.key.startsWith(pr) && (best === null || pr.length > best.length)) best = pr
    let denied = null
    const pols = best === null ? [] : routes.get(best).map((n) => policies.get(n))
