export class ParseError extends Error {}

export class Table {
  constructor() { this.map = new Map(); this.headerDefined = false }
}
export class ATable {
  constructor() { this.items = [] }
}
export class Arr {
  constructor() { this.items = [] }
}
export class Scalar {
  constructor(type, value) { this.type = type; this.value = value }
}

const fail = (m) => { throw new ParseError(m) }
const isWs = (c) => c === ' ' || c === '\t'
