const FLOAT = new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`)

class LineParser {
  constructor(line) { this.s = line; this.i = 0 }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  // end of meaningful content: end of line or comment start
  atEnd() { const c = this.s[this.i]; return c === undefined || c === '#' || c === ';' }

  string(q) {
    const s = this.s
    this.i++
    let out = ''
    for (;;) {
      const c = s[this.i]
      if (c === undefined) fail('unterminated string')
      if (c === q) { this.i++; return out }
      if (q === "'" || c !== '\\') { out += c; this.i++; continue }
      const e = s[this.i + 1]
      if (e === undefined) fail('unterminated string')
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, e)) { out += map[e]; this.i += 2 }
      else if (e === 'u') {
        const h = s.slice(this.i + 2, this.i + 6)
        if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16)); this.i += 6
      } else fail('invalid escape \\' + String.fromCodePoint(s.codePointAt(this.i + 1)))
    }
  }

  name() {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return this.string(c)
    const st = this.i
    while (isBare(this.s[this.i])) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const names = []
    for (;;) {
      this.ws()
      names.push(this.name())
      this.ws()
      if (this.s[this.i] === '.') this.i++
      else return names
    }
  }

  value(path) {
    this.ws()
    const c = this.s[this.i]
    if (c === undefined || c === ',' || c === ']' || c === '}' || c === '#' || c === ';') fail('expected a value')
    if (c === '"' || c === "'") return new Scalar('string', this.string(c))
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return new Scalar('boolean', true)
    if (w === 'false') return new Scalar('boolean', false)
    if (INT.test(w)) return new Scalar('integer', Number(w.replace(/_/g, '')))
    if (FLOAT.test(w)) return new Scalar('float', Number(w.replace(/_/g, '')))
    fail('invalid value ' + w)
  }

  array(path) {
    this.i++
    const arr = new Arr()
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.s[this.i] === ']') { this.i++; return arr }
      arr.items.push(this.value(`${path}[${arr.items.length}]`))
      this.ws()
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === ']') { this.i++; return arr }
      else fail('unterminated array')
