      if (c === ',') this.i++
      else if (c === '}') { this.i++; return t }
      else fail('unterminated inline table')
    }
  }
}

function walk(t, prefix, names) {
  let path = prefix
  for (const n of names) {
    path = join(path, n)
    let e = t.map.get(n)
    if (e === undefined) { e = new Table(); t.map.set(n, e) }
    if (e instanceof ATable) e = e.items[e.items.length - 1]
    if (!(e instanceof Table)) fail(`${path} is not a table`)
    t = e
  }
  return t
}

function assign(t, prefix, names, v) {
  const parent = walk(t, prefix, names.slice(0, -1))
  const full = join(prefix, names.join('.'))
  const last = names[names.length - 1]
  if (parent.map.has(last)) fail(`key ${full} is defined twice`)
  parent.map.set(last, v)
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = new Table()
  let cur = root
  let curPath = ''
  for (let n = 0; n < lines.length; n++) {
    try {
      const p = new LineParser(lines[n])
      p.ws()
      if (p.atEnd()) continue
      if (p.s[p.i] === '[') {
        const dbl = p.s[p.i + 1] === '['
        p.i += dbl ? 2 : 1
        const names = p.dotted()
        const close = (ch) => {
          if (p.s[p.i] === ch) p.i++
          else if (p.atEnd()) fail('unterminated table header')
          else fail('trailing text after a table header')
        }
        close(']')
        if (dbl) close(']')
        p.ws()
        if (!p.atEnd()) fail('trailing text after a table header')
        const parent = walk(root, '', names.slice(0, -1))
        const full = names.join('.')
        const last = names[names.length - 1]
        const e = parent.map.get(last)
        if (dbl) {
          if (e === undefined) { const a = new ATable(); parent.map.set(last, a); cur = new Table(); a.items.push(cur) }
          else if (e instanceof ATable) { cur = new Table(); e.items.push(cur) }
          else fail(`${full} is not an array of tables`)
        } else if (e === undefined) {
          cur = new Table(); cur.headerDefined = true; parent.map.set(last, cur)
        } else if (e instanceof Table) {
          if (e.headerDefined) fail(`table ${full} is defined twice`)
          e.headerDefined = true; cur = e
        } else fail(`${full} is not a table`)
        curPath = full
        continue
      }
      const names = p.dotted()
      if (p.s[p.i] !== '=') fail('expected key = value')
      p.i++
      const v = p.value(join(curPath, names.join('.')))
      p.ws()
      if (!p.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, names, v)
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${n + 1}: ${e.message}`
      throw e
    }
  }
  return root
}
