#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'
import { parse, ParseError, Table, ATable, Arr } from './parse.js'

const mode = process.argv.length === 3 ? process.argv[2] : undefined
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sorted = (t) => [...t.map.keys()].sort(cmp)

function toJson(v, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (v instanceof Table) {
    const ks = sorted(v)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${toJson(v.map.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (v instanceof ATable || v instanceof Arr) {
    if (!v.items.length) return '[]'
    return '[\n' + v.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(v.value)
}

function keys(v, path, out) {
  const kids = v instanceof Table
    ? sorted(v).map((k) => [path === '' ? k : `${path}.${k}`, v.map.get(k)])
    : v.items.map((x, i) => [`${path}[${i}]`, x])
  for (const [p, c] of kids) {
    const type = c instanceof Table ? 'table' : c instanceof ATable || c instanceof Arr ? 'array' : c.type
    out.push(`${p} ${type}`)
    if (!(type !== 'table' && type !== 'array')) keys(c, p, out)
  }
}

try {
  const doc = parse(readFileSync(0, 'utf8'))
  if (mode === 'json') process.stdout.write(toJson(doc, 0) + '\n')
  else {
    const out = []
    keys(doc, '', out)
    process.stdout.write(out.map((l) => l + '\n').join(''))
  }
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
