cat > src/run.js <<'EOF'
// Per-key policy state. Bucket tokens are stored scaled by `per` so partial
// periods stay exact: units = tokens * per.
function fresh(p, tick) {
  return p.kind === 'bucket' ? { units: p.capacity * p.per, last: tick } : { ticks: [] }
}

function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    const cap = p.capacity * p.per
    s.units += p.refill * (tick - s.last)
    if (s.units > cap) s.units = cap
    s.last = tick
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((x) => x > cut)
  }
}

const allows = (p, s) => (p.kind === 'bucket' ? s.units >= p.per : BigInt(s.ticks.length) < p.limit)

function record(p, s, tick) {
  if (p.kind === 'bucket') s.units -= p.per
  else s.ticks.push(tick)
}

export function run(mode, policies, routes, events) {
  const states = new Map()
  const counts = new Map()
  const out = []
  let ta = 0
  let td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const prefix of routes.keys()) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
    }
    let denied = null
    if (best !== null) {
      const list = routes.get(best)
      const ss = list.map((p) => {
        const id = p.name + '\0' + key
        if (!states.has(id)) states.set(id, fresh(p, tick))
        const s = states.get(id)
        advance(p, s, tick)
        return s
      })
      for (let i = 0; i < list.length; i++) {
        if (!allows(list[i], ss[i])) {
          denied = list[i]
          break
        }
      }
      if (!denied) list.forEach((p, i) => record(p, ss[i], tick))
    }
    const c = counts.get(key) || { a: 0, d: 0 }
    counts.set(key, c)
    if (denied) { c.d++; td++ } else { c.a++; ta++ }
    if (mode === 'replay') out.push(`${tick} ${key} ${denied ? 'deny ' + denied.name : 'allow'}`)
  }
  if (mode === 'summary') {
    for (const k of [...counts.keys()].sort()) out.push(`${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}`)
    out.push(`total allowed=${ta} denied=${td}`)
  }
  return out.length ? out.join('\n') + '\n' : ''
}
