const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function fail(n, reason) {
  const e = new Error(reason)
  e.limiterMessage = `line ${n}: ${reason}`
  throw e
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  const int = (n, field, s, least) => {
    if (!INT.test(s) || BigInt(s) < BigInt(least)) fail(n, `${field} must be an integer of at least ${least}`)
    return BigInt(s)
  }
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    const d = t[0]
    const decl = () => {
      if (events.length) fail(n, 'declarations must come before the first event')
    }
    if (d === 'bucket' || d === 'window') {
      const want = d === 'bucket' ? 5 : 4
      if (t.length !== want) {
        fail(n, d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
      }
      decl()
      if (!NAME.test(t[1])) fail(n, `invalid policy name ${t[1]}`)
      let p
      if (d === 'bucket') {
        const capacity = int(n, 'capacity', t[2], 1)
        const refill = int(n, 'refill', t[3], 0)
        const per = int(n, 'per', t[4], 1)
        p = { kind: 'bucket', name: t[1], capacity, refill, per }
      } else {
        const limit = int(n, 'limit', t[2], 0)
        const span = int(n, 'span', t[3], 1)
        p = { kind: 'window', name: t[1], limit, span }
      }
      if (policies.has(t[1])) fail(n, `policy ${t[1]} is declared twice`)
      policies.set(t[1], p)
    } else if (d === 'route') {
      if (t.length < 3) fail(n, 'expected route <prefix> <policy>...')
      decl()
      if (!NAME.test(t[1])) fail(n, `invalid route prefix ${t[1]}`)
      if (routes.has(t[1])) fail(n, `prefix ${t[1]} is routed twice`)
      const list = []
      for (const name of t.slice(2)) {
        if (!policies.has(name)) fail(n, `unknown policy ${name}`)
        list.push(policies.get(name))
      }
      routes.set(t[1], list)
    } else if (d === 'event') {
      if (t.length !== 3) fail(n, 'expected event <tick> <key>')
      const tick = int(n, 'tick', t[1], 0)
      if (!NAME.test(t[2])) fail(n, `invalid key ${t[2]}`)
      if (lastTick !== null && tick < lastTick) fail(n, `tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      events.push({ tick, key: t[2] })
    } else {
      fail(n, `unknown directive ${d}`)
    }
  })
  return { policies, routes, events }
}
